/* RPAssistant — подробные описания сил дисциплин V5 для подсказок при выборе.
   Пересказ механики своими словами (не цитаты из книг). Пул, цена, «против», амальгама и источник берутся из vtm.js.
   d — длительность; t — как работает. */
VTM.POW_FULL={
/* ---------- Анимализм ---------- */
bond_famulus:{d:'постоянно',t:'Вампир связывает одно животное узами крови: поит его витэ три ночи подряд и делает фамулусом. Фамулус понимает простые приказы без броска, а на него проще применять другие силы Анимализма (Язык животных к нему действует без проверки пробуждения). Одновременно фамулус может быть только один.'},
sense_beast:{d:'пассивно / сцена',t:'Вампир чувствует Зверя: замечает враждебность и агрессию вокруг, а при успешном броске понимает, что перед ним сверхъестественное существо (вампир, оборотень, одержимый) и насколько оно голодно или взбешено. Против того, кто скрывает свою природу, — встречный бросок.'},
animal_messenger:{d:'до доставки',t:'Вампир отправляет животное (обычно фамулуса) с посланием к конкретному человеку или месту. Животное находит адресата, если он в пределах досягаемости, и передаёт сообщение или предмет. С амальгамой Ясновидения вампир может смотреть глазами посланника.'},
atavism:{d:'сцена',t:'Вампир заставляет животное откатиться к звериным инстинктам: оно либо в ужасе бежит, либо бросается в атаку. Бросок против воли животного; у фамулуса сопротивления нет. Удобно, чтобы натравить сторожевую собаку на её же хозяев.'},
feral_whispers:{d:'сцена',t:'Вампир общается с животными: понимает их и может отдавать им приказы, либо призывает ближайших зверей определённого вида. Обаяние — чтобы убедить, Манипуляция — чтобы обмануть или принудить. Животные помнят мало и думают по-звериному, так что сложные вопросы бесполезны.'},
leash_beast:{d:'сцена',t:'Вампир помогает другому сородичу удержать своего Зверя: даёт бонус к сопротивлению Ярости и к броскам раскаяния. Можно потратить вторую проверку пробуждения, чтобы помочь сильнее. Требует амальгамы Стойкости.'},
tracing_blood:{d:'ночь',t:'Попробовав кровь цели, вампир может выследить её по запаху на любом расстоянии в пределах города. Успехи определяют, насколько точно и быстро он находит направление. След обрывается, если цель покинула город или пересекла текущую воду.'},
messengers_command:{d:'однократно',t:'Вампир вкладывает в животное-посланника силу Доминирования: когда животное встретит адресата и посмотрит ему в глаза, оно применит к нему Принуждение или Внушение вампира. Бросок Доминирования совершается, когда приказ передаётся.'},
animal_succulence:{d:'пассивно',t:'Кровь животных утоляет больше Голода — каждое животное снимает на 1 Голод больше обычного. Кроме того, ограничения Силы крови на кормление животными для вампира ослабевают на 2 уровня. Не позволяет опустить Голод до нуля.'},
plague_beasts:{d:'ночь',t:'Вампир метит человека, и все животные вокруг начинают его преследовать: собаки лают и кидаются, птицы кружат, крысы лезут из щелей. Это мешает цели скрываться, спать и работать. Цель сопротивляется Самообладанием + Обращением с животными.'},
quell_beast:{d:'сцена',t:'Вампир взглядом или прикосновением усмиряет Зверя. Смертный становится вялым и безразличным, не может проявлять инициативу; вампиру это силой гасит Ярость или Побуждение. При провале цель может, наоборот, взбеситься.'},
scent_prey:{d:'сцена',t:'Вампир чует, где поблизости есть подходящая жертва: свидетель, уязвимый человек, тот, чья кровь нужного резонанса. Даёт бонус к охоте и выслеживанию людей в толпе.'},
unliving_hive:{d:'постоянно',t:'Фамулусом вампира может стать рой насекомых. Рой живёт в теле вампира или в его логове, слушается простых команд и служит шпионом и оружием (может кусать, перекрывать обзор). Требует амальгамы Сокрытия.'},
augury:{d:'однократно',t:'Наблюдая за поведением животных, полётом птиц или внутренностями, вампир получает намёк на будущее или на ответ о текущей ситуации. Чем больше успехов, тем яснее знамение. Мастер отвечает образом, а не прямым текстом.'},
awaken_parasite:{d:'сцена',t:'Вампир пробуждает паразитов в теле цели: черви, вши и личинки начинают терзать её изнутри. Цель получает штрафы к действиям, а смертный — урон. Вампир сопротивляется Самообладанием + Упорством, смертный — Выносливостью + Смекалкой.'},
subsume_spirit:{d:'сцена',t:'Вампир переселяет разум в тело животного, обычно фамулуса, а его собственное тело лежит в оцепенении. Он видит и действует как это животное и может использовать некоторые свои дисциплины. Если животное погибает, вампир возвращается в тело с уроном Силе воли.'},
sway_flock:{d:'сцена',t:'Вампир разом управляет целым стадом, стаей или роем — животными одного вида поблизости. Цена растёт с размером группы. Животные действуют согласованно: окружают, нападают, отвлекают.'},
animal_dominion:{d:'сцена',t:'Вампир командует всеми животными в округе — не одним зверем, а целыми стаями. Количество успехов определяет, сколько их подчиняется и насколько сложные приказы они понимают. Подходит, чтобы натравить сотню крыс или разогнать птиц над кварталом.'},
coax_temper:{d:'сцена',t:'Вампир разжигает у другого сородича звериный нрав: тот получает Побуждение «Голод», «Агрессия» или другое по выбору применяющего, если не устоит. Требует контакта и бросок против Самообладания + Упорства цели.'},
drawing_out_beast:{d:'сцена',t:'Если вампир впадает в Ярость, он может выплеснуть своего Зверя в другого — смертного или сородича поблизости. Тот впадает в бешенство вместо вампира. Если цель сопротивится, Ярость остаётся с применяющим.'},
spirit_walk:{d:'сцена',t:'Вершина Анимализма: вампир может покидать тело и перемещаться между животными, перескакивая из одного в другое, как в Поглощении духа, но без возвращения в тело между прыжками.'},
/* ---------- Ясновидение ---------- */
heightened_senses:{d:'пока активно',t:'Чувства вампира становятся сверхчеловеческими: видит в почти полной темноте, слышит шёпот за стеной, различает запахи. К броскам восприятия добавляется рейтинг Ясновидения. Резкий свет или громкий звук может оглушить.'},
sense_unseen:{d:'пассивно',t:'Вампир замечает сверхъестественное, что скрыто от глаз: невидимых вампиров с Сокрытием, призраков, следы магии. Противостоит Сокрытию встречным броском. Смекалка — для внезапного, Упорство — для намеренного поиска.'},
panacea:{d:'однократно',t:'(Обиях) Вампир касается цели и успокаивает её разум: снимает страх, шок, последствия Ярости и часть урона Силе воли. Смертные засыпают и исцеляются быстрее. Требует амальгамы Стойкости.'},
premonition:{d:'пассивно / по запросу',t:'Вампира посещают видения и предчувствия. Пассивно мастер может давать подсказки; активно — вампир тратит проверку пробуждения и задаёт вопрос, получая символический ответ о ближайшем будущем.'},
reveal_temperament:{d:'однократно',t:'Вампир по крови или ауре определяет резонанс смертного (сангвиник, холерик, меланхолик, флегматик) и силу эмоции, а у сородича — его текущее настроение. Удобно для поиска нужной крови.'},
unerring_pursuit:{d:'ночь',t:'Вампир мысленно «привязывается» к цели, которую видел, и всегда чувствует направление к ней. Требует амальгамы Доминирования: цель должна была встретить его взгляд.'},
vermin_vision:{d:'сцена',t:'Вампир смотрит глазами насекомых, крыс и других паразитов поблизости, переключаясь между ними. Превращает каждую щель в шпиона. Требует Анимализма 2.'},
fatal_flaw:{d:'однократно',t:'Вампир изучает цель и находит её слабость: старая рана, страх, уязвимое место в защите. Следующая атака или социальное давление против этой слабости получает бонус. Требует амальгамы Обливиона.'},
scry_soul:{d:'однократно',t:'Вампир читает ауру: видит эмоции, резонанс, сверхъестественную природу, следы диаблери (чёрные прожилки) и признаки контроля чужим разумом. Каждый успех даёт ответ на вопрос о цели.'},
share_senses:{d:'сцена',t:'Вампир подключается к чувствам другого существа, которое знает, и видит и слышит то же, что оно. Цель не замечает этого, если не обладает Ясновидением. Работает на любом расстоянии, если вампир пробовал кровь цели.'},
haruspex:{d:'однократно',t:'Изучая кровь или внутренности жертвы, вампир узнаёт о её последних часах, болезнях и обстоятельствах смерти. Требует амальгамы Обливиона.'},
read_room:{d:'сцена',t:'Окинув взглядом собрание, вампир понимает расклад: кто с кем в союзе, кто боится, кто лжёт, кто главный. Даёт бонус к социальным броскам в этой сцене.'},
reveal_leash:{d:'однократно',t:'Вампир видит, находится ли цель под Кровными узами, Доминированием или чужим контролем, а при хорошем результате — и кто держит поводок.'},
spirits_touch:{d:'однократно',t:'(Психометрия) Касаясь предмета или места, вампир видит образы и эмоции, оставленные теми, кто был с ним связан: кто держал оружие, что происходило в комнате. Свежие и сильные события читаются легче.'},
heart_laid_bare:{d:'однократно',t:'Вампир видит самые глубокие желания и страхи цели — то, на что её можно поймать. Даёт бонус к манипуляции этой целью до конца истории.'},
clairvoyance:{d:'сцена',t:'Вампир впадает в транс и собирает сведения о районе, где он находится: кто приходил, что происходит, есть ли угроза. Каждый успех даёт ответ на вопрос или полезную деталь.'},
possession:{d:'сцена или дольше',t:'Вампир вселяется в смертного, глядя ему в глаза, и управляет его телом; собственное тело остаётся беззащитным. Нужна амальгама Доминирования 3. Смертный сопротивляется Упорством + Интеллектом.'},
telepathy:{d:'сцена',t:'Вампир читает поверхностные мысли цели и может передавать ей свои. Смертному не нужна проверка пробуждения, сородич сопротивляется Смекалкой + Хитростью. Глубокие воспоминания читать сложнее.'},
unburdening:{d:'однократно',t:'Вампир облегчает душу сородича: убирает пятна, снимает Побуждение или помогает справиться с последствиями Ярости. Требует амальгамы Доминирования 3.'},
/* ---------- Кровавое чародейство ---------- */
corrosive_vitae:{d:'однократно',t:'Кровь вампира становится едкой и разъедает неживую материю: замки, решётки, дерево, металл. Каждая проверка пробуждения проедает определённый объём. На живую плоть и вампиров не действует.'},
sanguine_sacrament:{d:'сцена',t:'Вампир формирует из собственной крови предметы: печать, нож, ключ, символ. Предметы непрочны и распадаются в конце сцены.'},
taste_for_blood:{d:'однократно',t:'Попробовав кровь, вампир узнаёт её резонанс, Силу крови и поколение сородича, недавно ли он пил кровь сородича (признаки диаблери). Чем больше успехов, тем больше сведений.'},
koldunic_sorcery:{d:'сцена',t:'Колдунская ветвь: вампир может творить ритуалы через стихии — землю, воду, огонь, ветер — привязанные к его земле. Позволяет понимать и применять колдунские ритуалы.'},
bloods_curse:{d:'сцена',t:'Вампир проклинает кровь цели: её витэ становится медленным и тяжёлым, проверки пробуждения проходят хуже, а смертному — болезнь. Цель сопротивляется Выносливостью + Оккультизмом или Стойкостью.'},
extinguish_vitae:{d:'однократно',t:'Вампир взглядом повышает Голод другого вампира: тот делает проверку пробуждения, а при большом успехе — две. Цель сопротивляется Выносливостью + Самообладанием.'},
scour_secrets:{d:'однократно',t:'Вампир использует кровь, чтобы быстро найти нужную информацию в книге, архиве или базе данных: часы чтения сжимаются до минут.'},
vinculum_magnum:{d:'постоянно',t:'Связанные кровью могут чувствовать эмоции друг друга и местоположение. Узы становятся «каналом» для других сил крови.'},
blood_of_potency:{d:'ночь',t:'Вампир временно повышает свою Силу крови на число успехов (но не выше 10 и не выше предела поколения +1). С ростом Силы крови растут прилив крови, лечение и бонус к дисциплинам. После окончания действия Голод может вырасти.'},
scorpions_touch:{d:'сцена',t:'Вампир превращает свою кровь в яд и наносит его на оружие или выплёвывает. Смертный теряет здоровье, вампир — Силу воли. Сила зависит от потраченных проверок пробуждения. Цель сопротивляется Выносливостью + Оккультизмом или Стойкостью.'},
transitive_bond:{d:'постоянно',t:'Кровные узы вампира можно передать через гуля или другого посредника: тот, кто выпьет кровь посредника, привязывается к самому вампиру.'},
ripples_heart:{d:'ночь',t:'Вампир меняет резонанс своей крови на нужный, чтобы управлять эмоциями тех, кто её пьёт, или выдавать себя за кого-то другого.'},
theft_of_vitae:{d:'однократно',t:'Вампир вытягивает кровь из жертвы на расстоянии прямой видимости: кровь течёт к нему по воздуху. Количество успехов определяет, сколько Голода снимается. Это заметно и нарушает Маскарад.'},
blood_aegis:{d:'сцена',t:'Вампир создаёт из крови щит, который поглощает урон. Каждая дополнительная проверка пробуждения усиливает щит.'},
fulminating_vitae:{d:'однократно',t:'Вампир взрывает кровь в жилах цели или в разлитой луже: взрыв наносит урон всем поблизости. Цель уклоняется Смекалкой + Атлетикой.'},
marionette:{d:'сцена',t:'Вампир управляет телом цели через её кровь, как марионеткой: заставляет двигаться, идти, держать оружие. Разум цели остаётся свободным. Сопротивление — Выносливость + Оккультизм или Стойкость.'},
baals_caress:{d:'сцена',t:'Вампир превращает кровь в смертельный яд и для сородичей: оружие с этой кровью наносит тяжёлый урон даже вампирам. Цель сопротивляется Выносливостью + Оккультизмом или Стойкостью.'},
cauldron_of_blood:{d:'однократно',t:'Вампир кипятит кровь в жилах цели касанием. Смертный обычно умирает, вампир получает тяжёлый урон по числу успехов. Цель сопротивляется Самообладанием + Оккультизмом или Стойкостью.'},
reclamation_vitae:{d:'однократно',t:'Вампир забирает обратно кровь, которой он кормил гулей или связанных узами, где бы они ни были. Применяющий получает пятна Человечности.'},
/* ---------- Стремительность ---------- */
cats_grace:{d:'пассивно',t:'Вампир автоматически проходит броски равновесия: ходит по канату, балкам, карнизам без проверки. Не помогает, если опоры нет.'},
fluent_swiftness:{d:'пассивно',t:'Вампир двигается плавно и быстро в обычной жизни: убирает штрафы за спешку и может выполнить простое действие мгновенно.'},
rapid_reflexes:{d:'пассивно',t:'Вампир не получает штрафа за защиту от нескольких противников и может совершать мелкие действия (выхватить оружие, встать, перезарядить) бесплатно, а не тратя на это ход.'},
fleetness:{d:'сцена',t:'Вампир добавляет рейтинг Стремительности к защите и к броскам Ловкости вне боя (не к атакам). Цена — проверка пробуждения.'},
rush_job:{d:'однократно',t:'Вампир выполняет за минуты то, что обычно занимает часы: обыск, ремонт, уборку, подготовку. Качество не страдает, но действие должно быть физическим.'},
blink:{d:'однократно',t:'Вампир за мгновение пересекает расстояние до цели, которое видит, — по прямой примерно до 50 метров — и может сразу атаковать. Бросок Ловкости + Атлетики против Сложности, зависящей от препятствий.'},
traversal:{d:'однократно',t:'Вампир бежит по вертикальным стенам или поверхности воды на высокой скорости. Остановка до конца пути приводит к падению. Бросок Ловкости + Атлетики.'},
weaving:{d:'сцена',t:'Вампир петляет так быстро, что в него сложнее попасть из огнестрельного оружия: добавляет Стремительность к защите от стрельбы.'},
thousand_cuts:{d:'сцена',t:'Вампир наносит множество мелких ударов, распределяя урон между несколькими противниками в зоне досягаемости.'},
blurred_momentum:{d:'сцена',t:'Вампир так быстр, что атаки с низким числом успехов проходят мимо: атакующий должен набрать больше успехов, чем рейтинг Стремительности, иначе промахивается.'},
draught_elegance:{d:'ночь',t:'Кровь вампира даёт пьющему его Стремительность на время. Гуль или смертный получает силы Стремительности по уровню вампира, но не больше их возможностей.'},
unerring_aim:{d:'однократно',t:'Вампир так быстр, что цель выстрела или броска не может уклониться: атака не встречает защиты, кроме сверхъестественной. Требует амальгамы Ясновидения 2.'},
unseen_strike:{d:'однократно',t:'Вампир атакует настолько быстро, что окружающие не видят ни его, ни удара — цель просто падает. Бросок против Смекалки + Наблюдательности свидетелей. Требует Сокрытия 4.'},
faster_than_light:{d:'сцена',t:'Вампир двигается настолько быстро, что успевает сделать несколько перемещений и действий за один ход.'},
lightning_strike:{d:'однократно',t:'Атака, от которой невозможно защититься: противник не может уклониться или парировать, кроме существ с аналогичной скоростью.'},
split_second:{d:'однократно',t:'Вампир действует в ответ на то, что только что произошло, и успевает раньше: перехватывает пулю, выхватывает предмет до удара, отменяет чужое действие, если это физически возможно за долю секунды.'},
/* ---------- Доминирование ---------- */
cloud_memory:{d:'постоянно',t:'Цель забывает последние несколько минут — обычно момент кормления или встречи с вампиром. Нужен взгляд в глаза. Против: Смекалка + Упорство.'},
compel:{d:'одно действие',t:'Короткий приказ из одного слова или фразы («Стоять!», «Брось!»), который цель выполняет немедленно, если это не ведёт к прямой угрозе её жизни. Нужен зрительный контакт. Против: Интеллект + Упорство.'},
slavish_devotion:{d:'пассивно',t:'Тех, кто находится под Доминированием вампира или связан с ним узами, труднее перехватить: чужое Доминирование на них получает штраф. Требует Стойкости 1.'},
mesmerize:{d:'до выполнения',t:'Сложный приказ, который цель выполняет, пока не закончит, — например, «Принеси мне документы из сейфа и забудь». Нужен зрительный контакт и понятная речь. Против: Интеллект + Упорство.'},
dementation:{d:'сцена',t:'Вампир разговором пробуждает в цели безумие: паранойю, бред, навязчивые мысли. Цель получает штрафы и может действовать иррационально. Требует амальгамы Сокрытия 2.'},
domitors_favor:{d:'пассивно',t:'Гулям и связанным узами вампира сложнее его предать или нарушить преданность — сопротивление узам у них снижается.'},
stolen_voice:{d:'сцена',t:'Вампир крадёт голос цели: может говорить её голосом или лишить её речи. Против: Упорство + Исполнение.'},
forgetful_mind:{d:'постоянно',t:'Вампир переписывает воспоминания цели: стирает, меняет или добавляет события. Чем больше успехов, тем детальнее изменение. Против: Интеллект + Упорство.'},
submerged_directive:{d:'до триггера',t:'Приказ, отданный Внушением, можно отложить: цель выполнит его, когда произойдёт условие («когда увидишь Принца»), и не будет знать почему.'},
chain_command:{d:'сцена',t:'Подчинённый вампиру может передать его приказ дальше: цель Доминирования становится «рупором» и применяет приказ к другим.'},
ancestral_dominion:{d:'однократно',t:'Вампир применяет Доминирование к любому своему кровному потомку без зрительного контакта. Требует Кровавого чародейства 2.'},
implant_suggestion:{d:'долго',t:'Вампир меняет убеждения или чувства цели — например, заставляет ненавидеть союзника — и цель считает их своими. Требует Величия 1.'},
rationalize:{d:'пассивно',t:'Жертвы Доминирования объясняют свои действия собственными причинами и не подозревают о вмешательстве.'},
tabula_rasa:{d:'постоянно',t:'Вампир полностью стирает личность и память цели, превращая её в «чистый лист». Против: Самообладание + Упорство.'},
lethes_call:{d:'постоянно',t:'Вампир стирает из памяти цели целые годы или события, в том числе у сородичей. Против: Интеллект + Упорство.'},
mass_manipulation:{d:'как у силы',t:'Вампир применяет Доминирование не к одной цели, а к группе, которая на него смотрит: бросок против самой сильной воли в группе.'},
terminal_decree:{d:'пассивно',t:'Приказы Доминирования могут заставить цель причинить себе вред или убить себя — обычные ограничения самосохранения не действуют.'},
/* ---------- Стойкость ---------- */
fluent_endurance:{d:'пассивно',t:'Вампир выносливее в повседневности: не устаёт, выдерживает холод и жару, а штрафы от лёгких ран применяются позже.'},
resilience:{d:'пассивно',t:'К клеткам здоровья добавляется рейтинг Стойкости.'},
unswayable_mind:{d:'пассивно',t:'К сопротивлению Доминированию, Величию и другим силам, влияющим на разум, добавляется рейтинг Стойкости.'},
earths_perseverance:{d:'сцена',t:'Вампира невозможно сдвинуть с места, если он сам этого не хочет: удары, толчки и захваты не сбивают его с ног.'},
enduring_beasts:{d:'сцена',t:'Вампир передаёт часть своей Стойкости животным рядом — фамулусу или стае. Требует Анимализма 1.'},
invigorating_vitae:{d:'однократно',t:'Кровь вампира мгновенно исцеляет смертного: каждая выпитая порция убирает урон. Требует Ясновидения 1.'},
obdurate:{d:'сцена',t:'Вампира невозможно отбросить, сбить или опрокинуть — даже взрывом или машиной. Требует Мощи 2.'},
toughness:{d:'сцена',t:'Вычитает рейтинг Стойкости из каждого источника лёгкого урона (до нуля).'},
self_assurance:{d:'сцена',t:'Вампир устойчивее к социальному давлению и страху: добавляет Стойкость к сопротивлению запугиванию и манипуляции.'},
defy_bane:{d:'сцена',t:'Вампир превращает тяжёлый урон (огонь, солнце, когти) в лёгкий в пределах рейтинга Стойкости. Бросок Смекалки + Выживания.'},
fortify_facade:{d:'пассивно',t:'Вампира сложнее прочитать Ясновидением: добавляет Стойкость к сопротивлению чтению мыслей, ауры и чувств.'},
seal_maw:{d:'сцена',t:'Вампир запечатывает своего Зверя: не может впасть в Ярость и получить Побуждение до конца сцены, но и не может питаться.'},
valeren:{d:'однократно',t:'Вампир исцеляет другого сородича: тратит свою кровь, чтобы убрать урон у цели. Требует Ясновидения 1.'},
calloused_soul:{d:'сцена',t:'Вампир на время глушит совесть: не получает пятна Человечности за поступки в этой сцене, но платит пятнами позже.'},
draught_endurance:{d:'ночь',t:'Кровь вампира даёт пьющему его Стойкость: гуль или смертный получает силы Стойкости по уровню вампира.'},
gorgons_scales:{d:'сцена',t:'Кожа вампира становится твёрдой как камень: дополнительная защита от любого физического урона.'},
shatter:{d:'однократно',t:'Когда вампира бьют оружием, оно ломается о его тело.'},
flesh_of_marble:{d:'сцена',t:'Вампир игнорирует первый источник физического урона за каждый ход (кроме солнца и огня).'},
prowess_from_pain:{d:'сцена',t:'Вампир не получает штрафов от ран, а урон усиливает его атрибуты: каждый уровень урона добавляет к одному атрибуту.'},
meat_shields:{d:'сцена',t:'Вампир перенаправляет часть урона на гулей и связанных узами рядом с ним: они получают урон вместо него.'},
/* ---------- Сокрытие ---------- */
cloak_shadows:{d:'пока неподвижен',t:'Вампир становится невидимым, пока стоит неподвижно в тени или укрытии. Любое движение или шум раскрывают его.'},
ensconce:{d:'сцена',t:'Вампир прячет небольшой предмет на себе или рядом — его не замечают при обыске.'},
silence_death:{d:'сцена',t:'Вампир не издаёт звуков: шаги, дыхание, хлопанье дверей. Работает только на звуки, которые он производит сам.'},
mask_of_ages:{d:'сцена',t:'Вампир выглядит старше или моложе своих лет, меняя видимый возраст в пределах человеческого.'},
cache:{d:'ночь',t:'Вампир прячет предмет так, что его никто не замечает, даже если будет искать.'},
chimerstry:{d:'сцена',t:'Вампир создаёт краткую иллюзию для одного чувства: звук, образ, запах. Иллюзия не может причинить вред. Против: Самообладание + Смекалка. Требует Величия 1.'},
ghosts_passing:{d:'сцена',t:'Вампир не оставляет следов и запаха — его нельзя выследить ни людям, ни собакам. Требует Анимализма 1.'},
unseen_passage:{d:'сцена',t:'Вампир остаётся невидимым даже в движении. Резкие действия (атака, громкий шум) раскрывают его.'},
ventriloquism:{d:'сцена',t:'Вампир говорит так, что его слышит только один выбранный человек. Требует Ясновидения 2.'},
doubletalk:{d:'сцена',t:'Вампир говорит фразу, которую одни слушатели слышат как обычную, а другие — как скрытое послание. Требует Ясновидения 1.'},
fata_morgana:{d:'сцена',t:'Сложные иллюзии для всех чувств сразу: можно создать фигуру, комнату, толпу. Требует Величия 2.'},
ghost_machine:{d:'пассивно',t:'Сокрытие действует и на технику: вампира не видно на камерах, записях и в прямой трансляции.'},
mask_thousand:{d:'сцена',t:'Вампир выглядит неприметным человеком, которого никто не запоминает — свидетели не могут описать его лицо.'},
mask_isolation:{d:'сцена',t:'Вампир маскирует жертву так, что её никто не замечает и не узнаёт. Требует Доминирования 1.'},
mental_maze:{d:'сцена',t:'Цель теряется в знакомом месте: не может найти выход, ходит кругами. Цена растёт с длительностью. Требует Доминирования 1.'},
mind_masque:{d:'сцена',t:'Вампир скрывает свои мысли и эмоции, показывая ложные при попытке чтения. Требует Доминирования 2.'},
guise_departed:{d:'сцена',t:'Вампир принимает облик недавно умершего, которого видел. Требует Обливиона 1.'},
conceal:{d:'ночь',t:'Вампир скрывает крупный неподвижный объект — дом, машину, вход. Требует Ясновидения 3.'},
vanish:{d:'сцена',t:'Вампир исчезает прямо на глазах у наблюдателей. Против: Смекалка + Наблюдательность.'},
seclusion:{d:'сцена',t:'Вампир скрывает от окружающих комнату или помещение. Требует Доминирования 1.'},
cloak_gathering:{d:'сцена',t:'Вампир распространяет Сокрытие на спутников — до числа, определённого рейтингом.'},
impostors_guise:{d:'сцена',t:'Вампир принимает облик конкретного человека, которого видел. Против: Манипуляция + Исполнение.'},
conceal:{d:'ночь',t:'Вампир скрывает крупный неподвижный объект — машину, дверь, вход в убежище, иногда небольшой дом. Пока сила действует, люди проходят мимо, не замечая его, а камеры показывают пустое место. Ясновидение может пробить сокрытие встречным броском. Требует амальгамы Ясновидения 3.'},
vanish:{d:'сцена',t:'Вампир исчезает прямо на глазах у наблюдателей, даже посреди разговора или погони, и сразу оказывается под действием Незримой поступи. Свидетели сопротивляются Смекалкой + Наблюдательностью; у смертных, кто не прошёл бросок, воспоминание о моменте исчезновения размывается.'},
cloak_gathering:{d:'сцена',t:'Вампир распространяет свои силы Сокрытия на спутников рядом — число дополнительных людей зависит от рейтинга Сокрытия. Если любой из спрятанных себя выдаст, раскрывается только он сам; если раскроется вампир — все.'},
impostors_guise:{d:'сцена',t:'Вампир принимает облик конкретного человека, которого внимательно рассматривал: лицо, голос, манеры. Знакомые с оригиналом могут заметить подмену броском против Манипуляции + Исполнения применяющего. Не копирует знания и воспоминания.'},
mask_thousand:{d:'сцена',t:'Вампир выглядит как неприметный незнакомец: свидетели видят обычного человека подходящего для места вида и не могут потом его описать. С успехом можно выглядеть конкретным типом людей (охранник, курьер), но не конкретным человеком.'},
ghost_machine:{d:'пассивно',t:'Силы Сокрытия вампира действуют и на технику: его не видно на камерах наблюдения, записях и в прямых трансляциях, а голос не записывается, пока сила активна. Без этой силы техника «видит» спрятавшегося вампира.'},
/* ---------- Обливион ---------- */
ashes_to_ashes:{d:'однократно',t:'Касаясь трупа, вампир превращает его в прах — улика исчезает за несколько минут. На оживлённых мертвецов и гулей действует как атака: они сопротивляются Выносливостью + Медициной (или Стойкостью) и получают урон. Ветвь некромантии.'},
binding_fetter:{d:'сцена',t:'Вампир видит оковы — предметы, места и людей, которые удерживают призраков в мире живых, — и чувствует, к какому духу они привязаны. Позволяет найти призрака, договориться с ним или пригрозить уничтожить его оковы. Ветвь некромантии.'},
oblivion_sight:{d:'сцена',t:'Глаза вампира темнеют: он видит в абсолютной темноте, в том числе в тьме, созданной Обливионом, и замечает призраков и духов, находящихся рядом. Ветвь теней.'},
shadow_cloak:{d:'сцена',t:'Тени окутывают вампира, искажая его очертания. Он получает бонус к Скрытности и к Запугиванию, а также защиту от стрельбы в полутьме. Ветвь теней.'},
arms_ahriman:{d:'сцена',t:'Вампир вызывает из теней щупальца, которые хватают, держат и бьют врагов. Щупальца действуют по командам вампира, пока он сосредоточен; их число и сила зависят от рейтинга. Требует амальгамы Мощи 2. Ветвь теней.'},
fatal_prediction:{d:'однократно',t:'Вампир предсказывает цели скорую беду и тем самым притягивает её: в ближайшее время цель попадает в неприятности, а броски против неё получают бонус. Против: Смекалка + Оккультизм. Требует Ясновидения 2. Ветвь некромантии.'},
fatal_precognition:{d:'однократно',t:'Видение подсказывает, как и когда цель может умереть, если ничего не изменится. Можно предупредить союзника или подготовить ловушку. Требует Ясновидения 2. Ветвь некромантии.'},
shadow_cast:{d:'сцена',t:'Вампир отбрасывает живую тень или создаёт область тьмы. В ней смертные получают штрафы, а те, кто плохо видит в темноте, почти слепы. Ветвь теней.'},
where_veil_thins:{d:'сцена',t:'Вампир ощущает, насколько тонок Саван между миром живых и мёртвых в этом месте: где легче вызвать призрака, провести ритуал или где произошла насильственная смерть. Ветвь некромантии.'},
aura_decay:{d:'сцена',t:'Вокруг вампира всё начинает гнить и ломаться: еда портится, металл ржавеет, техника отказывает, а живые чувствуют тошноту. Смертные и гули сопротивляются Выносливостью + Медициной или Стойкостью, иначе получают штрафы. Ветвь некромантии.'},
passion_feast:{d:'однократно',t:'Вампир питается страстями призрака, а не кровью: снимает Голод, поглощая эмоции духа, который рядом. Призрак сопротивляется Упорством + Самообладанием. Требует Стойкости 2. Ветвь некромантии.'},
shadow_perspective:{d:'сцена',t:'Вампир переносит свои чувства в любую тень, которую видит или хорошо знает, и смотрит и слушает оттуда, оставаясь на месте. Ветвь теней.'},
shadow_servant:{d:'сцена',t:'Вампир отделяет от себя тень и отправляет её разведать или передать сообщение. Тень видит и слышит для хозяина. Требует Ясновидения 1. Ветвь теней.'},
touch_oblivion:{d:'однократно',t:'Касание вампира иссушает плоть: цель получает урон, а у смертного поражённая часть тела сохнет и немеет. Наносится как атака без оружия. Ветвь теней.'},
necrotic_plague:{d:'долго',t:'Вампир насылает на цель болезнь: смертный слабеет и может умереть без лечения, вампир получает штрафы. Против: Выносливость + Медицина или Стойкость. Ветвь некромантии.'},
profane_sanctified:{d:'однократно',t:'Вампир оскверняет святое место или реликвию, лишая её защитной силы против сородичей. Противостоит вере тех, кто держит святыню, — проверка их Воли.'},
stygian_shroud:{d:'сцена',t:'Вампир окутывает область плотной тьмой Стигии: внутри ничего не видно даже с Обострением чувств, а смертные теряют ориентацию. Сам вампир и обладатели Взора бездны видят. Ветвь теней.'},
umbrous_clutch:{d:'однократно',t:'Тень цели хватает её и удерживает на месте или утаскивает в темноту. Против: Ловкость + Смекалка. Цена — проверка пробуждения и пятно. Ветвь теней.'},
darkness_within:{d:'однократно',t:'Вампир наполняет тело цели тьмой: она получает тяжёлый урон изнутри и паникует. Против: Самообладание + Упорство.'},
shadow_step:{d:'однократно',t:'Вампир входит в одну тень и выходит из другой, которую видит или знает, в пределах около ста метров. Может взять с собой одного спутника. Ветвь теней.'},
skuld_fulfilled:{d:'однократно',t:'Вампир возвращает цели болезни и раны, от которых она когда-то оправилась: у смертного открываются старые переломы и болезни, гуль теряет защиту от старения. Против: Выносливость + Выносливость или Стойкость. Ветвь некромантии.'},
tenebrous_avatar:{d:'сцена',t:'Вампир превращается в живую тень: проходит в щели, скользит по стенам, неуязвим для обычного оружия, но уязвим для огня и солнца. Ветвь теней.'},
withering_spirit:{d:'однократно',t:'Вампир разрушает дух цели: та теряет Силу воли и может впасть в отчаяние или кому. Против: Упорство + Оккультизм или Стойкость. Цена — две проверки и пятна. Ветвь некромантии.'},
/* ---------- Мощь ---------- */
fluent_strength:{d:'пассивно',t:'Вампир легко делает повседневные силовые вещи — поднимает тяжести, выбивает двери — без броска, если задача не требует настоящего усилия.'},
lethal_body:{d:'пассивно',t:'Удары вампира без оружия наносят смертным тяжёлый урон, а не лёгкий. Против вампиров урон обычный. Кулак может пробить тонкие стены и броню.'},
soaring_leap:{d:'однократно',t:'Вампир прыгает на высоту или в длину, кратную рейтингу Мощи (примерно 3 метра вверх и 9 метров в длину за каждую точку).'},
prowess:{d:'сцена',t:'Добавляет рейтинг Мощи к урону от атак без оружия и в ближнем бою, а также к броскам Силы для подвигов силы. Цена — проверка пробуждения.'},
relentless_grasp:{d:'сцена',t:'Захват вампира невозможно разорвать обычной силой: цель может вырваться, только если у неё тоже есть Мощь или сверхъестественная сила.'},
brutal_feed:{d:'однократно',t:'Вампир за секунды выпивает жертву досуха, разрывая горло. Голод снимается сразу, но это обычно убивает смертного и выглядит ужасно — серьёзный риск для Маскарада и Человечности.'},
exuberance:{d:'сцена',t:'Сила вампира переливается через край: он двигается широко и мощно, получает бонус к Запугиванию и физическим социальным действиям.'},
spark_of_rage:{d:'сцена',t:'Вампир заражает толпу или человека яростью: начинаются драки, люди срываются на других. Против: Самообладание + Интеллект. Требует Величия 3.'},
uncanny_grip:{d:'сцена',t:'Вампир держится за любую поверхность — стену, потолок, гладкое стекло — и может по ним лазать, оставляя вмятины в материале.'},
wrecker:{d:'сцена',t:'Вампир удваивает Мощь при разрушении предметов и строений: ломает стены, двери, машины.'},
draught_might:{d:'ночь',t:'Кровь вампира даёт пьющему его Мощь: гуль или смертный получает силы Мощи по уровню вампира.'},
crash_down:{d:'однократно',t:'Вампир прыгает с высоты и обрушивается на землю, нанося урон всем вокруг точки приземления. Цели уклоняются Ловкостью + Атлетикой.'},
earthshock:{d:'однократно',t:'Вампир бьёт по земле, и ударная волна сбивает с ног всех в радиусе нескольких метров. Цели проходят бросок, чтобы устоять.'},
fist_of_caine:{d:'сцена',t:'Удары вампира без оружия наносят тяжёлый урон даже сородичам и другим сверхъестественным существам.'},
subtle_hammer:{d:'пассивно',t:'Вампир полностью контролирует свою силу: может ударить так, чтобы ничего не сломать, или вложить всю Мощь в один точный удар.'},
/* ---------- Величие ---------- */
awe:{d:'сцена',t:'Вампир излучает притяжение: окружающие тянутся к нему и хотят его слушать. Добавляет рейтинг Величия к Убеждению, Исполнению и Лидерству. Не работает против тех, кто уже настроен враждебно.'},
daunt:{d:'сцена',t:'Вампир излучает угрозу: окружающие боятся приблизиться и не хотят ссориться. Добавляет рейтинг Величия к Запугиванию. Нельзя одновременно использовать с Благоговением.'},
eyes_serpent:{d:'пока смотрит',t:'Взгляд вампира парализует: смертный или вампир, встретивший его глаза, не может двигаться, пока вампир не отведёт взгляд или не будет атакован. Против: Смекалка + Самообладание. Требует Метаморфоз 1.'},
lingering_kiss:{d:'пассивно',t:'Укус вампира вызывает сильнейшее удовольствие: жертвы жаждут его снова, соглашаются на кормление и добавляют вампиру бонус к социальным броскам. Может вызывать зависимость.'},
melpominee:{d:'сцена',t:'Вампир может говорить и петь так, что его голос слышат на большом расстоянии, и вкладывать в него силы Величия.'},
predators_lure:{d:'сцена',t:'Вампир становится особенно привлекательным для определённого типа жертвы — она сама ищет встречи. Против: Самообладание + Упорство.'},
clear_field:{d:'однократно',t:'Вампир заставляет всех в помещении, кроме выбранных, уйти. Против: Смекалка + Самообладание. Требует Доминирования 3.'},
dread_gaze:{d:'однократно',t:'Вампир показывает свою чудовищную природу взглядом: цель в ужасе убегает или застывает. Против: Самообладание + Упорство.'},
entrancement:{d:'длительно',t:'Цель влюбляется в вампира и становится услужливой: выполняет просьбы, считает его другом. Против: Самообладание + Смекалка.'},
passion_leech:{d:'однократно',t:'Вампир вытягивает эмоции из цели, утоляя Голод. Требует Ясновидения 2.'},
thrown_voice:{d:'сцена',t:'Вампир заставляет свой голос звучать из другого места, вкладывая в него Величие. Требует Ясновидения 1.'},
true_loves_face:{d:'сцена',t:'Цель видит в вампире того, кого любит больше всех. Против: Самообладание + Смекалка. Требует Сокрытия 3.'},
invigorating_display:{d:'сцена',t:'Вампир воодушевляет союзников своим выступлением, давая им бонусы.'},
inflame_desire:{d:'сцена',t:'Вампир разжигает в цели желание обладать чем-то или кем-то. Против: Самообладание + Упорство. Требует Сокрытия 1.'},
irresistible_voice:{d:'пассивно',t:'Доминирование вампира действует через голос, без зрительного контакта. Требует Доминирования 1.'},
magnum_opus:{d:'постоянно',t:'Вампир вкладывает Величие в произведение искусства. Требует Ясновидения 3.'},
suffuse_edifice:{d:'ночь',t:'Вампир наполняет здание своим Величием.'},
summon:{d:'однократно',t:'Цель, которую вампир встречал, приходит к нему. Против: Самообладание + Интеллект.'},
wingman:{d:'сцена',t:'Вампир распространяет своё Величие на союзника.'},
majesty:{d:'сцена',t:'Никто не смеет действовать против вампира. Против: Самообладание + Упорство.'},
star_magnetism:{d:'пассивно',t:'Силы Величия работают через экран.'},
passion_leech:{d:'однократно',t:'Вампир вдыхает сильную эмоцию стоящего рядом человека — страх, восторг, страсть — и утоляет ею Голод без укуса. Жертва после этого чувствует опустошение. Требует амальгамы Ясновидения 2.'},
thrown_voice:{d:'сцена',t:'Вампир заставляет свой голос звучать из любой точки, которую видит, и может применять оттуда силы Величия, основанные на голосе, оставаясь незамеченным. Требует Ясновидения 1.'},
true_loves_face:{d:'сцена',t:'Цель видит в вампире человека, которого любит или любила больше всех, — с его лицом и голосом — и реагирует соответственно. Против: Самообладание + Смекалка. Требует амальгамы Сокрытия 3.'},
invigorating_display:{d:'сцена',t:'Яркое выступление вампира (речь, танец, музыка) воодушевляет союзников: они восстанавливают Силу воли или получают бонус к следующему броску.'},
inflame_desire:{d:'сцена',t:'Вампир раздувает в цели одно желание — к человеку, вещи, мести — до одержимости. Цель стремится его удовлетворить, забывая об осторожности. Против: Самообладание + Упорство. Требует Сокрытия 1.'},
irresistible_voice:{d:'пассивно',t:'Силы Доминирования вампира действуют через голос — по телефону, через стену, в темноте, — зрительный контакт не нужен. Запись голоса не работает. Требует амальгамы Доминирования 1.'},
magnum_opus:{d:'постоянно',t:'Вампир вкладывает Величие в созданное им произведение — картину, песню, текст. Каждый, кто его видит или слышит, испытывает заложенную эмоцию. Цена растёт с силой эффекта. Требует Ясновидения 3.'},
suffuse_edifice:{d:'ночь',t:'Вампир наполняет своим Величием здание или зал: Благоговение или Угроза действуют на всех внутри, даже когда его самого нет рядом.'},
summon:{d:'однократно',t:'Вампир зовёт человека, которого встречал или кровь которого пробовал. Тот бросает дела и приходит к вампиру кратчайшим путём, не понимая, зачем. Против: Самообладание + Интеллект.'},
wingman:{d:'сцена',t:'Вампир переносит свою притягательность на союзника: окружающие тянутся к тому, кого вампир выберет, и охотнее идут с ним на контакт.'},
majesty:{d:'сцена',t:'Окружающие не смеют действовать против вампира: не атакуют его, не перечат и не уходят без разрешения. Чтобы преодолеть эффект на одно действие, нужно пройти бросок Самообладания + Упорства против успехов вампира.'},
star_magnetism:{d:'пассивно',t:'Силы Величия вампира работают через экран и динамик — на видеозвонке, в прямом эфире, на концерте по трансляции. Для записанного видео обычно не действуют.'},
/* ---------- Метаморфозы ---------- */
eyes_of_beast:{d:'пока активно',t:'Глаза вампира наливаются красным светом: он видит в полной темноте без штрафов. Светящиеся глаза пугают смертных и дают бонус к Запугиванию.'},
squirm:{d:'однократно',t:'Вампир на миг меняет кости и суставы, чтобы выскользнуть из захвата, оков или протиснуться в узкую щель.'},
weight_feather:{d:'пока активно',t:'Вампир становится почти невесомым: не получает урона от падения, не проваливается, может прыгать дальше. Бросок Смекалки + Выживания, чтобы активировать в ответ на внезапное падение.'},
feral_weapons:{d:'сцена',t:'У вампира вырастают когти или удлиняются клыки. Атаки ими получают бонус к урону и наносят тяжёлый урон смертным. Не считаются оружием при обыске.'},
vicissitude:{d:'постоянно',t:'Вампир лепит собственную плоть и кости: меняет лицо, рост, добавляет шипы или броню. Изменения постоянны, пока их не переделают. Требует амальгамы Доминирования 2.'},
serpents_kiss:{d:'сцена',t:'Язык и челюсть вампира становятся змеиными: он может кормиться, не оставляя следов укуса, и вливать в жертву слабый яд.'},
false_sip:{d:'однократно',t:'Вампир делает вид, что пьёт кровь или ест, и тело действительно принимает пищу без рвоты. Помогает сохранять Маскарад за столом. Требует Стойкости 1.'},
earth_meld:{d:'день',t:'Вампир погружается в землю и проводит в ней день, защищённый от солнца. Выйти можно только ночью; если над ним разроют землю, он пробуждается.'},
fleshcrafting:{d:'постоянно',t:'Вампир лепит плоть другого существа — смертного, гуля или вампира. Может изуродовать, исцелить или изменить внешность. Нежелающая цель сопротивляется Выносливостью + Упорством. Требует Доминирования 2.'},
shapechange:{d:'до отмены',t:'Вампир превращается в животное примерно своего размера — волка, крупную собаку. Сохраняет разум, получает звериные чувства и способности, но не может говорить. Одежда не превращается.'},
visceral_absorption:{d:'однократно',t:'Вампир поглощает плоть и кровь трупа или раненого, утоляя Голод и уничтожая улики. Требует Кровавого чародейства 2.'},
masque_death:{d:'сцена',t:'Вампир выглядит как давно мёртвый труп: окоченевший, бледный, холодный. Обманывает даже медиков и сверхъестественное восприятие. Требует Обливиона 2.'},
horrid_form:{d:'сцена',t:'Вампир превращается в чудовищную боевую форму: огромный рост, броня из кости, когти. Получает большие бонусы к физическим атрибутам и урону. Нарушает Маскарад одним видом. Требует Доминирования 2.'},
metamorphosis:{d:'до отмены',t:'Вампир превращается в любое животное — от летучей мыши до медведя — или в стаю мелких животных. Размер может отличаться от его собственного.'},
blood_form:{d:'сцена',t:'Тело вампира превращается в лужу крови: он перетекает под дверями, неуязвим к обычному оружию и может быть выпит. Требует Кровавого чародейства 2.'},
heart_darkness:{d:'постоянно',t:'Вампир вынимает своё сердце и прячет его. Кол в грудь его больше не парализует, но если сердце найдут и уничтожат — он погибнет. Требует Стойкости 2.'},
master_forms:{d:'пассивно',t:'Вампир свободно сочетает формы Метаморфоз: может частично превращаться и переходить из одной формы в другую без лишней цены.'},
mist_form:{d:'до отмены',t:'Вампир превращается в туман: проходит сквозь щели, неуязвим к физическому урону (кроме огня и солнца), медленно перемещается по воздуху. Чем быстрее нужно превратиться, тем больше проверок пробуждения.'},
one_with_land:{d:'ночь / день',t:'Вампир сливается с землёй своего домена и может перемещаться внутри неё, выходя из земли в любой точке домена. Требует Анимализма 2.'},
swarm:{d:'сцена',t:'Вампир превращается в рой насекомых или летучих мышей. Рой может атаковать, проникать в щели и разделяться, но если большая часть роя погибнет, вампир получает урон.'},
unfettered_heart:{d:'пассивно',t:'Сердце вампира свободно перемещается внутри тела, так что кол почти никогда не попадает в него: попытка пронзить сердце требует гораздо больше успехов.'},
face_victim:{d:'сцена',t:'Вампир принимает облик человека, которого только что выпил досуха, — лицо, голос, рост. Хорош для того, чтобы заменить жертву.'},
/* ---------- Алхимия слабокровных ---------- */
body_paint:{d:'сцена',t:'Формула меняет цвет кожи и волос вампира, рисует или скрывает татуировки. Помогает маскироваться. Бросок Ловкости + Ремесла определяет качество.'},
checkout_time:{d:'однократно',t:'Формула позволяет слабокровному впасть в короткий сон и проснуться в нужное время, игнорируя усталость от солнца.'},
elevate:{d:'сцена',t:'Формула позволяет вампиру парить и медленно подниматься в воздухе, как будто он невесом.'},
far_reach:{d:'сцена',t:'Телекинез: вампир двигает предметы на расстоянии силой мысли. Бросок Упорства + Алхимии; вес и скорость зависят от уровня и успехов. Можно атаковать, бросая предметы.'},
food_stain:{d:'однократно',t:'Формула позволяет «окрасить» кровь, которую вампир выпьет, нужным резонансом.'},
gaolers_bane:{d:'однократно',t:'Формула размягчает замки, наручники и решётки, позволяя легко освободиться.'},
haze:{d:'сцена',t:'Вокруг вампира возникает облако тумана, скрывающее его и дающее бонус к Скрытности; смертные внутри плохо видят.'},
mercurian_tongue:{d:'сцена',t:'Вампир говорит на любом языке, который слышит, — формула временно даёт понимание и речь.'},
plug_in:{d:'сцена',t:'Вампир подключается к электронному устройству и управляет им напрямую: читает данные, открывает двери, отключает сигнализацию. Бросок Упорства + Алхимии.'},
portable_shade:{d:'сцена',t:'Вампир создаёт вокруг себя тень, которая частично защищает от солнечного света. Бросок Выносливости + Алхимии.'},
speak_heart:{d:'сцена',t:'Цель говорит вампиру правду о своих чувствах.'},
advanced_torpor:{d:'по выбору',t:'Вампир входит в торпор и выходит из него, когда захочет, — удобно, чтобы переждать опасность или вылечиться.'},
blacklight_surprise:{d:'сцена',t:'Формула делает кровь вампира светящейся в ультрафиолете — для ловушек и меток.'},
blood_mandagloire:{d:'сцена',t:'Подготовка к Мандаглуару: вампир смешивает кровь с другим слабокровным для совместного эффекта.'},
blue_state:{d:'сцена',t:'Вампир успокаивается и становится холодным: бонус к сопротивлению Ярости и к ментальным броскам.'},
envelop:{d:'сцена',t:'Туман окутывает цель, ослепляя и душа её. Бросок Смекалки + Алхимии; цель получает штрафы и не видит.'},
friends_list:{d:'однократно',t:'Вампир получает доступ к контактам и связям цели через её телефон или соцсети. Бросок Интеллекта + Алхимии.'},
mirror_trust:{d:'сцена',t:'Цель доверяет вампиру, как себе.'},
reds_hot_sauce:{d:'однократно',t:'Острая смесь, вызывающая сильную реакцию у вампира, который её выпьет: Голод растёт или начинается Ярость.'},
whiff_its:{d:'сцена',t:'Вампир чувствует запах сверхъестественного. Бросок Упорства + Наблюдательности.'},
counterfeit2:{d:'сцена',t:'Слабокровный подделывает силу любой дисциплины 2-го уровня, которую он видел или пробовал у сородича. Действует как оригинал, но временно.'},
bleed_out:{d:'однократно',t:'Вампир заставляет рану цели кровоточить сильнее.'},
chem_flashback:{d:'однократно',t:'Химический состав вызывает у цели яркое воспоминание.'},
concoct_ashe:{d:'однократно',t:'Вампир варит «пепел» — наркотик из праха вампира, дающий видения и временные силы. Бросок Интеллекта + Алхимии.'},
diamond_skin:{d:'сцена',t:'Кожа вампира твердеет, давая защиту.'},
defractionate:{d:'однократно',t:'Вампир восстанавливает свойства консервированной или испорченной крови: кровь из пакетов снова утоляет Голод.'},
fang_stinger:{d:'сцена',t:'Клыки вампира выделяют яд. Бросок Упорства + Алхимии.'},
fireskin:{d:'сцена',t:'Кожа вампира становится огнеупорной.'},
freezer_fluid:{d:'однократно',t:'Кровь вампира замораживает то, на что попадёт. Бросок Упорства + Алхимии.'},
hospital_chains:{d:'сцена',t:'Цель приковывается к месту. Против: Выносливость.'},
mandagloire:{d:'сцена',t:'Несколько слабокровных объединяют силы в одной формуле. Бросок Выносливости + Алхимии.'},
martian_purity:{d:'сцена',t:'Кровь вампира очищается от наркотиков и ядов.'},
mask_off:{d:'однократно',t:'Вампир снимает маскировку или иллюзию с цели.'},
sunburn:{d:'однократно',t:'Вампир вызывает на цели ожоги, как от солнца.'},
profane_hieros:{d:'сцена',t:'Вампир меняет свой облик и пол. Бросок Выносливости + Упорства определяет, насколько полно изменение.'},
rumor:{d:'долго',t:'Вампир запускает слух, который распространяется сам. Бросок Манипуляции + Алхимии.'},
stay_sand:{d:'сцена',t:'Вампир замедляет время для себя или цели. Бросок Упорства + Алхимии.'},
saraimu:{d:'сцена',t:'Формула вызывает у цели видения прошлого. Бросок Упорства + Алхимии.'},
tank:{d:'сцена',t:'Вампир становится крайне выносливым.'},
tlc:{d:'однократно',t:'Вампир лечит раны цели.'},
troll_pious:{d:'однократно',t:'Вампир лишает святыню силы.'},
counterfeit3:{d:'сцена',t:'Подделка любой дисциплины 3-го уровня, которую слабокровный видел или пробовал.'},
airborne_momentum:{d:'сцена',t:'Вампир летает, разгоняясь телекинезом. Бросок Силы + Алхимии.'},
copycat:{d:'сцена',t:'Вампир копирует внешность и голос цели.'},
disc_channeling:{d:'сцена',t:'Вампир передаёт силу дисциплины другому.'},
halfliving_conductor:{d:'сцена',t:'Вампир проводит электричество через себя. Бросок Выносливости + Алхимии.'},
hollow_leg:{d:'сцена',t:'Вампир может пить бесконечно. Бросок Интеллекта + Алхимии.'},
juice_box:{d:'однократно',t:'Вампир консервирует кровь.'},
red_state:{d:'сцена',t:'Вампир впадает в боевое бешенство под контролем.'},
short_circuit:{d:'однократно',t:'Вампир выводит из строя электронику рядом.'},
toxic_personality:{d:'сцена',t:'Кровь и пот вампира становятся ядовитыми. Бросок Силы или Ловкости + Алхимии.'},
vitae_msg:{d:'однократно',t:'Вампир делает кровь вкуснее для сородичей.'},
counterfeit4:{d:'сцена',t:'Подделка любой дисциплины 4-го уровня.'},
awaken_sleeper:{d:'однократно',t:'Вампир пробуждает сородича из торпора, независимо от его Силы крови.'},
beast_mode:{d:'сцена',t:'Вампир высвобождает Зверя в полную силу.'},
da_bomb:{d:'однократно',t:'Вампир создаёт взрывчатку из крови.'},
flowering_amaranth:{d:'однократно',t:'Вампир совершает диаблери и получает сильные бонусы. Бросок Упорства + Алхимии.'},
moment_clarity:{d:'однократно',t:'Вампир на миг становится полноценным сородичем.'},
saturns_flux:{d:'сцена',t:'Вампир меняет свою Силу крови.'},
counterfeit5:{d:'сцена',t:'Подделка любой дисциплины 5-го уровня.'},
/* ---------- дополнения к кратким описаниям ---------- */
resilience:{d:'пассивно',t:'К клеткам здоровья вампира добавляется рейтинг Стойкости — он выдерживает больше урона до торпора. Действует постоянно, без проверки пробуждения.'},
toughness:{d:'сцена',t:'Из каждого источника лёгкого урона вычитается рейтинг Стойкости (урон не может стать меньше нуля). Тяжёлый урон не уменьшает. Цена — проверка пробуждения на сцену.'},
shatter:{d:'сцена',t:'Когда вампира бьют оружием ближнего боя и атака не пробивает его стойкость, оружие ломается о его тело. Удобно против дубинок и ножей; огнестрел не ломается.'},
flesh_of_marble:{d:'сцена',t:'Кожа вампира твердеет как камень: первый источник физического урона за каждый ход полностью игнорируется (не действует на огонь, солнце и сверхъестественные атаки). Цена — две проверки пробуждения.'},
ensconce:{d:'сцена',t:'Вампир прячет на себе небольшой предмет — нож, пистолет, флешку. Пока он держит предмет при себе, тот не замечают при обыске и досмотре, если обыскивающий не владеет Ясновидением.'},
cache:{d:'ночь',t:'Вампир прячет предмет в определённом месте так, что посторонние не замечают его, даже если ищут целенаправленно. Сам вампир и те, кому он покажет, находят его без труда.'},
ventriloquism:{d:'сцена',t:'Вампир говорит так, что слышит только один выбранный слушатель, даже в толпе или на расстоянии прямой видимости. Окружающие не замечают разговора. Требует Ясновидения 2.'},
guise_departed:{d:'сцена',t:'Вампир принимает облик умершего человека, чей труп или призрак видел, и обманывает тех, кто его знал. Цель видит именно покойного, а не случайного незнакомца. Требует Обливиона 1.'},
seclusion:{d:'сцена',t:'Вампир «прячет» комнату вместе с теми, кто внутри: снаружи её не замечают, проходят мимо двери, звуки из неё не слышны. Против: Упорство + Наблюдательность. Требует Доминирования 1.'},
wrecker:{d:'сцена',t:'Вампир с невероятной лёгкостью ломает неживые предметы и постройки: двери, машины, стены. Бонус Мощи к таким броскам удваивается.'},
elevate:{d:'сцена',t:'Формула позволяет слабокровному медленно парить и подниматься в воздухе. Скорость невысокая, это не полёт, а левитация. Бросок Выносливости + Алхимии.'},
food_stain:{d:'однократно',t:'Слабокровный «окрашивает» свою или чужую кровь нужным резонансом с помощью еды или препарата. Подробности — в Blood Sigils.'},
gaolers_bane:{d:'однократно',t:'Формула ослабляет замки, наручники и решётки, позволяя слабокровному выбраться из заключения. Подробности — в Winter’s Teeth.'},
mercurian_tongue:{d:'сцена',t:'Слабокровный временно понимает любой язык, который слышит, и может на нём говорить. Помогает с иностранцами и шифрованной речью.'},
speak_heart:{d:'сцена',t:'Формула побуждает цель говорить откровенно о своих чувствах и мотивах. Подробности — в Blood Sigils.'},
blacklight_surprise:{d:'сцена',t:'Формула делает метки из крови вампира видимыми только в ультрафиолете — для тайных знаков, ловушек и маркировки. Подробности — в Blood Sigils.'},
mirror_trust:{d:'сцена',t:'Цель проникается к слабокровному доверием, как к самой себе, и охотнее делится информацией. Подробности — в Second Inquisition.'},
whiff_its:{d:'сцена',t:'Слабокровный чувствует по запаху присутствие сверхъестественных существ и следы их пребывания. Бросок Упорства + Наблюдательности.'},
bleed_out:{d:'однократно',t:'Формула заставляет рану цели кровоточить сильнее и дольше, усугубляя урон. Подробности — в Tattered Façade.'},
chem_flashback:{d:'однократно',t:'Химический состав вызывает у цели яркое воспоминание — так можно узнать то, что она забыла или скрыла. Подробности — в Cults of the Blood Gods.'},
diamond_skin:{d:'сцена',t:'Кожа слабокровного твердеет, давая защиту от физического урона на время действия формулы. Подробности — в Blood Sigils.'},
fang_stinger:{d:'сцена',t:'Клыки слабокровного выделяют яд, который ослабляет жертву при укусе. Бросок Упорства + Алхимии. Подробности — в Second Inquisition.'},
fireskin:{d:'сцена',t:'Кожа слабокровного становится огнестойкой: урон от огня снижается на время действия формулы. Подробности — в Blood Sigils.'},
freezer_fluid:{d:'однократно',t:'Кровь слабокровного резко охлаждается и замораживает то, на что попадёт. Бросок Упорства + Алхимии. Подробности — в Second Inquisition.'},
hospital_chains:{d:'сцена',t:'Формула приковывает цель к месту или к кровати, лишая подвижности. Против: Выносливость. Подробности — в Blood Sigils.'},
mandagloire:{d:'сцена',t:'Несколько слабокровных объединяют кровь, чтобы совместно применить формулу сильнее, чем мог бы каждый поодиночке. Бросок Выносливости + Алхимии.'},
martian_purity:{d:'сцена',t:'Кровь слабокровного очищается от наркотиков, ядов и примесей, полученных при кормлении. Подробности — в Blood Sigils.'},
mask_off:{d:'однократно',t:'Формула срывает с цели маскировку — иллюзию, изменённую внешность или Сокрытие. Подробности — в Blood Sigils.'},
sunburn:{d:'однократно',t:'Слабокровный вызывает у цели ожоги, похожие на солнечные: вампиры получают урон, смертные — болезненные раны.'},
rumor:{d:'долго',t:'Слабокровный запускает слух, который сам распространяется по сообществу и обрастает подробностями. Бросок Манипуляции + Алхимии определяет размах.'},
stay_sand:{d:'сцена',t:'Формула словно замедляет течение времени для цели: она действует медленнее, а слабокровный успевает больше. Бросок Упорства + Алхимии.'},
saraimu:{d:'сцена',t:'Формула вызывает у цели видения прошлого, связанные с местом или предметом. Бросок Упорства + Алхимии. Подробности — в Tattered Façade.'},
tank:{d:'сцена',t:'Слабокровный становится очень выносливым: получает дополнительную защиту и игнорирует часть штрафов от ран.'},
tlc:{d:'однократно',t:'Формула лечит раны цели — смертного или вампира. Подробности — в Blood Sigils.'},
troll_pious:{d:'однократно',t:'Слабокровный подрывает силу веры: истинная вера или святыня теряет защитный эффект против него. Подробности — в Blood Sigils.'},
counterfeit3:{d:'сцена',t:'Слабокровный подделывает силу любой дисциплины 3-го уровня, которую он видел или пробовал на себе: формула воспроизводит эффект оригинала на время действия.'},
airborne_momentum:{d:'сцена',t:'Слабокровный летает, разгоняя себя телекинезом. Скорость и манёвренность зависят от успехов броска Силы + Алхимии.'},
copycat:{d:'сцена',t:'Слабокровный копирует внешность и голос цели, которую пробовал или видел вблизи. Подробности — в Blood Sigils.'},
disc_channeling:{d:'сцена',t:'Слабокровный передаёт силу дисциплины, которой владеет, другому существу на время. Подробности — в Cults of the Blood Gods.'},
halfliving_conductor:{d:'сцена',t:'Тело слабокровного проводит электричество: он может пропускать ток через себя, не получая урона, и бить им врагов. Бросок Выносливости + Алхимии.'},
hollow_leg:{d:'сцена',t:'Слабокровный может пить и есть сколько угодно без вреда — для Маскарада за столом или для перевозки крови. Бросок Интеллекта + Алхимии.'},
juice_box:{d:'однократно',t:'Слабокровный консервирует кровь так, чтобы она дольше сохраняла резонанс и свойства. Подробности — в Gehenna War.'},
red_state:{d:'сцена',t:'Слабокровный впадает в контролируемое боевое бешенство: получает бонусы в бою, не теряя полностью контроль. Подробности — в Blood Sigils.'},
short_circuit:{d:'однократно',t:'Слабокровный выводит из строя электронику рядом с собой: камеры, телефоны, освещение.'},
toxic_personality:{d:'сцена',t:'Кровь и пот слабокровного становятся ядовитыми для тех, кто его кусает или касается. Бросок Силы или Ловкости + Алхимии при атаке.'},
vitae_msg:{d:'однократно',t:'Формула делает кровь особенно вкусной и желанной для сородичей — можно приманить или отвлечь их. Подробности — в Blood Sigils.'},
counterfeit4:{d:'сцена',t:'Подделка любой дисциплины 4-го уровня, которую слабокровный видел или пробовал. Действует как оригинал, но временно.'},
awaken_sleeper:{d:'однократно',t:'Слабокровный пробуждает сородича из торпора — независимо от его Силы крови и того, сколько тот должен был спать.'},
beast_mode:{d:'сцена',t:'Слабокровный высвобождает Зверя в полную силу, получая мощные физические бонусы ценой контроля. Подробности — в Gehenna War.'},
da_bomb:{d:'однократно',t:'Слабокровный превращает кровь во взрывчатку, которую можно бросить или заложить. Подробности — в Tattered Façade.'},
flowering_amaranth:{d:'однократно',t:'Формула, связанная с диаблери: даёт слабокровному особые преимущества при поглощении чужой крови. Бросок Упорства + Алхимии. Подробности — в Players Guide.'},
moment_clarity:{d:'однократно',t:'На короткое время слабокровный становится полноценным сородичем: получает свойства обычного вампира и может использовать дисциплины без ограничений слабой крови.'},
saturns_flux:{d:'сцена',t:'Слабокровный временно меняет свою Силу крови. Подробности — в Blood Sigils.'},
counterfeit5:{d:'сцена',t:'Подделка любой дисциплины 5-го уровня, которую слабокровный видел или пробовал. Действует как оригинал, но временно.'},
};
